function getTableauTranslation(key, lang) {
    if (tableauTranslations[lang] && tableauTranslations[lang][key]) {
        return tableauTranslations[lang][key];
    }
    if (tableauTranslations.en && tableauTranslations.en[key]) {
        return tableauTranslations.en[key];
    }
    return null;
}

function applyTableauTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.tableau.')) {
            const translation = getTableauTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyTableauTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyTableauTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyTableauTranslations(currentLang);
}


